package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class AssetCustodyAcceptance {
 static String api(String id){return "/api/openservice/assets/"+id+"/custody";}
 static String record(String id){return "/api/now/table/alm_asset/"+id;}
 static String create(WorkflowSupport h,String tag)throws Exception{return result(h.json("POST","/api/now/table/alm_asset",map("short_description","Retained equipment","description","Staff equipment custody","asset_tag",tag,"model","Field laptop","serial_number","SN-001"),auth("AssetKeeper"))).get("sys_id").toString();}
 static String[] setup(WorkflowSupport h)throws Exception{try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String name:List.of("AssetKeeper","AssetOther","AssetUser","AssetReader"))Service.createAccount(db,map("name",name,"role",name.equals("AssetReader")?"reader":name.equals("AssetUser")?"requester":"agent","password",PASSWORD));db.connection.commit();}return new String[]{create(h,"INV-001"),h.add("stockroom").get("sys_id").toString(),h.add("cmdb_ci").get("sys_id").toString()};}
 static Map<String,Object> body(WorkflowSupport h,String id,String operation)throws Exception{var p=get(h,api(id),"AssetKeeper");return map("operation",operation,"revision",object(p.get("movement")).get("revision"),"record_revision",Integer.parseInt(object(p.get("record")).get("sys_mod_count").toString()),"reason","Physical equipment movement verified");}
 static Map<String,Object> save(WorkflowSupport h,String id,Map<String,Object> body)throws Exception{return result(h.json("POST",api(id),body,auth("AssetKeeper")));}
 static Map<String,Object> receive(WorkflowSupport h,String[] ids)throws Exception{var b=body(h,ids[0],"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",ids[2]));return save(h,ids[0],b);}
 static void issue(WorkflowSupport h,String id)throws Exception{var b=body(h,id,"issue");b.put("username","AssetUser");save(h,id,b);}
 static void returned(WorkflowSupport h,String id,String stock)throws Exception{var b=body(h,id,"return");b.put("stockroom_id",stock);save(h,id,b);}
 static void retire(WorkflowSupport h,String id)throws Exception{var b=body(h,id,"retire");b.put("disposition","donated");save(h,id,b);}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);assertTrue(objects(get(h,api(ids[0]),"AssetKeeper").get("history")).isEmpty());var ci=get(h,"/api/now/table/cmdb_ci/"+ids[2],"AssetKeeper");receive(h,ids);assertEquals("in_stock",object(get(h,api(ids[0]),"AssetKeeper").get("movement")).get("state"));assertEquals(409,h.json("DELETE","/api/now/table/stockroom/"+ids[1],map(),auth("admin")).statusCode());issue(h,ids[0]);var p=get(h,api(ids[0]),"AssetKeeper");assertEquals("AssetUser",object(object(p.get("movement")).get("assignee")).get("name"));assertTrue(object(object(p.get("movement")).get("stockroom")).isEmpty());assertEquals(403,h.get(api(ids[0]),auth("AssetUser")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE name='AssetUser'");db.connection.commit();}assertEquals(0,object(object(get(h,api(ids[0]),"AssetKeeper").get("movement")).get("assignee")).get("active"));String destination=h.add("stockroom").get("sys_id").toString();returned(h,ids[0],destination);assertTrue(object(object(get(h,api(ids[0]),"AssetKeeper").get("movement")).get("assignee")).isEmpty());assertEquals(destination,object(object(get(h,api(ids[0]),"AssetKeeper").get("movement")).get("stockroom")).get("sys_id"));retire(h,ids[0]);p=get(h,api(ids[0]),"AssetKeeper");assertEquals("retired",object(p.get("record")).get("state"));assertEquals(false,p.get("can_edit"));assertEquals(4,objects(p.get("history")).size());assertEquals("donated",object(object(p.get("movement")).get("detail")).get("disposition"));assertEquals(ci.get("state"),get(h,"/api/now/table/cmdb_ci/"+ids[2],"AssetKeeper").get("state"));assertEquals(409,h.json("DELETE",record(ids[0]),map(),auth("admin")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/stockroom/"+destination,map(),auth("admin")).statusCode());new Store(h.environment);assertEquals(4,objects(get(h,api(ids[0]),"AssetKeeper").get("history")).size());String next=create(h,"INV-002");receive(h,new String[]{next,ids[1],ids[2]});assertEquals(ids[2],object(get(h,api(next),"AssetKeeper").get("ci")).get("sys_id"));
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);assertEquals(401,h.get(api(ids[0]),null).statusCode());assertEquals(405,h.json("PATCH",api(ids[0]),map(),auth("AssetKeeper")).statusCode());assertEquals(400,h.get(api(ids[0])+"?x=y",auth("AssetKeeper")).statusCode());assertEquals(400,h.json("POST",api(ids[0]),map("operation","unknown"),auth("AssetKeeper")).statusCode());assertEquals(409,h.json("PATCH",record(ids[0]),map("state","in_stock"),auth("AssetKeeper")).statusCode());for(var bad:List.of(map("extra",1),map("stockroom_id",""),map("ci_id",123),map("reason",""),map("revision","0"))){var b=body(h,ids[0],"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",""));b.putAll(bad);assertEquals(400,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());}for(String field:List.of("revision","record_revision")){var b=body(h,ids[0],"receive");b.putAll(map("stockroom_id",ids[1],"ci_id","",field,999));assertEquals(409,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());}var early=body(h,ids[0],"return");early.put("stockroom_id",ids[1]);assertEquals(409,h.json("POST",api(ids[0]),early,auth("AssetKeeper")).statusCode());result(h.json("PATCH","/api/now/table/stockroom/"+ids[1],map("state","retired"),auth("admin")));var b=body(h,ids[0],"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",""));assertEquals(409,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());result(h.json("PATCH","/api/now/table/stockroom/"+ids[1],map("state","active"),auth("admin")));save(h,ids[0],b);try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE name='AssetUser'");db.connection.commit();}var inactive=body(h,ids[0],"issue");inactive.put("username","AssetUser");assertEquals(400,h.json("POST",api(ids[0]),inactive,auth("AssetKeeper")).statusCode());for(String username:List.of("unknown","")){b=body(h,ids[0],"issue");b.put("username",username);assertEquals(400,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());}b=body(h,ids[0],"retire");b.put("disposition","lost");assertEquals(400,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());assertEquals(1,objects(get(h,api(ids[0]),"AssetKeeper").get("history")).size());assertEquals(409,h.json("PATCH",record(ids[0]),map("state","in_use"),auth("AssetKeeper")).statusCode());for(String state:List.of("in_stock","in_use","retired"))assertEquals(409,h.json("POST","/api/openservice/import/alm_asset?dry_run=false",List.of(map("sys_id",Values.id(),"short_description","Forged custody","state",state)),auth("admin")).statusCode());String empty=create(h,"UNRECEIVED");assertEquals(204,h.json("DELETE",record(empty),map(),auth("admin")).statusCode());
 }
 static void identity(WorkflowSupport h)throws Exception{
  var ids=setup(h);for(String tag:List.of("","bad tag","!bad")){result(h.json("PATCH",record(ids[0]),map("asset_tag",tag),auth("AssetKeeper")));var b=body(h,ids[0],"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",ids[2]));assertEquals(400,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());}result(h.json("PATCH",record(ids[0]),map("asset_tag","Inv-001"),auth("AssetKeeper")));Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"alm_asset");}var gated=new LinkedHashMap<>(original);gated.put("transition_rules",map("in_stock",map("min_approvals",1)));ReferencePickerAcceptance.writeSchema(h,"alm_asset",gated);try{var blocked=body(h,ids[0],"receive");blocked.putAll(map("stockroom_id",ids[1],"ci_id",ids[2]));assertEquals(409,h.json("POST",api(ids[0]),blocked,auth("AssetKeeper")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_asset_identity WHERE record_id=?",ids[0]));assertEquals(0,db.count("SELECT COUNT(*) FROM os_asset_movement WHERE record_id=?",ids[0]));}}finally{ReferencePickerAcceptance.writeSchema(h,"alm_asset",original);}receive(h,ids);assertEquals(400,h.json("PATCH",record(ids[0]),map("asset_tag","different"),auth("AssetKeeper")).statusCode());result(h.json("PATCH",record(ids[0]),map("asset_tag","INV-001"),auth("AssetKeeper")));String duplicate=create(h,"inv-001");var b=body(h,duplicate,"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",""));assertEquals(409,h.json("POST",api(duplicate),b,auth("AssetKeeper")).statusCode());result(h.json("PATCH",record(duplicate),map("asset_tag","INV-002"),auth("AssetKeeper")));b=body(h,duplicate,"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",ids[2]));assertEquals(409,h.json("POST",api(duplicate),b,auth("AssetKeeper")).statusCode());b.put("ci_id",Values.id());assertEquals(404,h.json("POST",api(duplicate),b,auth("AssetKeeper")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_asset_identity WHERE record_id=?",duplicate));}b.put("ci_id","");save(h,duplicate,b);assertTrue(object(get(h,api(duplicate),"AssetKeeper").get("ci")).isEmpty());
 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);for(String table:List.of("stockroom","cmdb_ci")){Map<String,Object> originalTable;try(var db=h.store.open()){originalTable=Service.schema(db,table);}var schema=new LinkedHashMap<>(originalTable);var roles=new LinkedHashMap<>(object(originalTable.getOrDefault("record_roles",map())));roles.put("read",List.of("admin"));schema.put("record_roles",roles);ReferencePickerAcceptance.writeSchema(h,table,schema);try{assertTrue(objects(get(h,api(ids[0]),"AssetKeeper").get(table.equals("stockroom")?"stockrooms":"cis")).isEmpty());assertEquals(200,h.get("/assets",auth("AssetKeeper")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,table,originalTable);}}for(String table:List.of("alm_asset","stockroom")){Map<String,Object> originalTable;try(var db=h.store.open()){originalTable=Service.schema(db,table);}var schema=new LinkedHashMap<>(originalTable);var roles=new LinkedHashMap<>(object(originalTable.getOrDefault("record_roles",map())));roles.put("create",List.of("admin"));schema.put("record_roles",roles);ReferencePickerAcceptance.writeSchema(h,table,schema);try{assertFalse(html(h.get("/assets",auth("AssetKeeper"))).contains("href=\"/record/"+table+"/new\""));}finally{ReferencePickerAcceptance.writeSchema(h,table,originalTable);}}Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"alm_asset");}var hiddenName=new LinkedHashMap<>(original);hiddenName.put("field_rules",map("short_description",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"alm_asset",hiddenName);try{var rendered=h.get("/record/alm_asset/"+ids[0]+"/custody",auth("AssetKeeper"));assertEquals(200,rendered.statusCode());assertTrue(html(rendered).contains("Inventory asset"));assertFalse(object(get(h,api(ids[0]),"AssetKeeper").get("record")).containsKey("short_description"));}finally{ReferencePickerAcceptance.writeSchema(h,"alm_asset",original);}for(String field:List.of("asset_tag","model","serial_number")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"alm_asset",schema);try{assertEquals(403,h.get(api(ids[0]),auth("AssetKeeper")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"alm_asset",original);}}for(String field:List.of("update","state")){var b=body(h,ids[0],"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",ids[2]));var schema=new LinkedHashMap<>(original);if(field.equals("update")){var roles=new LinkedHashMap<>(object(original.get("record_roles")));roles.put("update",List.of("admin"));schema.put("record_roles",roles);}else schema.put("field_rules",map("state",map("type","string","write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"alm_asset",schema);try{assertEquals(false,get(h,api(ids[0]),"AssetKeeper").get("can_edit"));assertEquals(403,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"alm_asset",original);}}var allowed=new LinkedHashMap<>(original);allowed.put("field_rules",map("state",map("type","string","write_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"alm_asset",allowed);receive(h,ids);ReferencePickerAcceptance.writeSchema(h,"alm_asset",original);for(String table:List.of("stockroom","cmdb_ci")){String linked=table.equals("stockroom")?ids[1]:ids[2];ProblemInvestigationsAcceptance.access(h,table,linked,"private",FieldDispatchAcceptance.uid(h,"AssetOther"));var p=get(h,api(ids[0]),"AssetKeeper");assertFalse(JSON.writeValueAsString(p).contains(linked));if(table.equals("stockroom")){var b=body(h,ids[0],"issue");b.put("username","AssetUser");assertEquals(404,h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode());}ProblemInvestigationsAcceptance.access(h,table,linked,"workspace","");}ProblemInvestigationsAcceptance.access(h,"alm_asset",ids[0],"private",FieldDispatchAcceptance.uid(h,"AssetOther"));assertEquals(404,h.get(api(ids[0]),auth("AssetKeeper")).statusCode());assertEquals(0,objects(get(h,"/api/openservice/assets","AssetKeeper").get("items")).size());assertEquals("0",object(get(h,"/api/now/stats/alm_asset?sysparm_count=true","AssetKeeper").get("stats")).get("count"));assertTrue(objects(parsed(h.get("/export/alm_asset",auth("AssetKeeper"))).get("result")).isEmpty());assertEquals(403,h.get(api(ids[0]),auth("AssetReader")).statusCode());
 }
 static void concurrency(WorkflowSupport h)throws Exception{
  var ids=setup(h);var b=body(h,ids[0],"receive");b.putAll(map("stockroom_id",ids[1],"ci_id",""));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode();});var c=pool.submit(()->{start.await();return h.json("POST",api(ids[0]),b,auth("AssetKeeper")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),c.get()));}try(var db=h.store.open()){var row=db.one("SELECT * FROM os_asset_movement WHERE record_id=?",ids[0]);for(int n=2;n<1000;n++)db.update("INSERT INTO os_asset_movement(record_id,revision,state,stockroom_id,assignee_id,detail) VALUES(?,?,?,?,?,?)",ids[0],n,row.get("state"),row.get("stockroom_id"),row.get("assignee_id"),JSON.writeValueAsString(row.get("detail")));db.connection.commit();}issue(h,ids[0]);assertEquals(1000,objects(get(h,api(ids[0]),"AssetKeeper").get("history")).size());var last=body(h,ids[0],"return");last.put("stockroom_id",ids[1]);assertEquals(400,h.json("POST",api(ids[0]),last,auth("AssetKeeper")).statusCode());assertEquals("in_use",get(h,record(ids[0]),"AssetKeeper").get("state"));
 }
}
